int cherryPickup(int** grid, int gridSize, int* gridColSize) {
    (void)gridColSize;
    int n = gridSize;
    const int NEG = -1000000000;

    int* dp = (int*)malloc((size_t)n * n * sizeof(int));
    int* ndp = (int*)malloc((size_t)n * n * sizeof(int));
    for (int i = 0; i < n * n; ++i) dp[i] = NEG;
    dp[0] = grid[0][0];

    for (int k = 1; k <= 2 * n - 2; ++k) {
        for (int i = 0; i < n * n; ++i) ndp[i] = NEG;
        int lo = k - n + 1;
        if (lo < 0) lo = 0;
        int hi = k < n - 1 ? k : n - 1;

        for (int r1 = lo; r1 <= hi; ++r1) {
            int c1 = k - r1;
            if (grid[r1][c1] == -1) continue;
            for (int r2 = lo; r2 <= hi; ++r2) {
                int c2 = k - r2;
                if (grid[r2][c2] == -1) continue;

                int best = dp[r1 * n + r2];
                if (r1 > 0 && dp[(r1 - 1) * n + r2] > best)
                    best = dp[(r1 - 1) * n + r2];
                if (r2 > 0 && dp[r1 * n + (r2 - 1)] > best)
                    best = dp[r1 * n + (r2 - 1)];
                if (r1 > 0 && r2 > 0 && dp[(r1 - 1) * n + (r2 - 1)] > best)
                    best = dp[(r1 - 1) * n + (r2 - 1)];
                if (best == NEG) continue;

                int gain = grid[r1][c1];
                if (r1 != r2) gain += grid[r2][c2];
                ndp[r1 * n + r2] = best + gain;
            }
        }
        int* tmp = dp; dp = ndp; ndp = tmp;
    }

    int result = dp[(n - 1) * n + (n - 1)];
    if (result < 0) result = 0;
    free(dp);
    free(ndp);
    return result;
}

