            int hi = min(n - 1, k);

            for (int r1 = lo; r1 <= hi; ++r1) {
                int c1 = k - r1;
                if (grid[r1][c1] == -1) continue;

                for (int r2 = lo; r2 <= hi; ++r2) {
                    int c2 = k - r2;
                    if (grid[r2][c2] == -1) continue;

                    int best = dp[r1][r2];
                    if (r1 > 0) best = max(best, dp[r1 - 1][r2]);
                    if (r2 > 0) best = max(best, dp[r1][r2 - 1]);
                    if (r1 > 0 && r2 > 0) best = max(best, dp[r1 - 1][r2 - 1]);
                    if (best == NEG) continue;

                    int gain = grid[r1][c1];
                    if (r1 != r2) gain += grid[r2][c2];
                    ndp[r1][r2] = best + gain;
                }
            }
